css:
.nutflows{
  color-scheme:light;
  --bg:#f5f1e8;
  --paper:#fcfaf6;
  --paper-2:#f0e8dc;
  --ink:#181410;
  --muted:#6c6158;
  --line:#ded4c7;
  --line-strong:#c8b7a3;
  --brown:#6f4428;
  --brown-2:#a86b3b;
  --olive:#5d6f4c;
  --olive-2:#92a26f;
  --gold:#b48a45;
  --shadow:0 14px 40px rgba(48,32,20,.08);
  --radius:22px;
  --radius-sm:16px;
  --serif:Iowan Old Style,Georgia,Times New Roman,serif;
  --sans:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
*{box-sizing:border-box}

.nutflows{min-height:100vh;margin:0;font-family:var(--sans);color:var(--ink);line-height:1.45;background:
  radial-gradient(circle at 0% 0%, rgba(180,138,69,.12), transparent 24%),
  radial-gradient(circle at 100% 0%, rgba(111,68,40,.06), transparent 18%),
  linear-gradient(180deg,#f8f4ed 0%, var(--bg) 45%, #eee6d9 100%)}
a{color:inherit;text-underline-offset:3px}
button{font:inherit}
.wrap{width:min(1240px, calc(100% - 40px)); margin-inline:auto}
.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;z-index:99;padding:10px 12px;border-radius:12px;background:#111;color:#fff}
.topbar{position:sticky;top:0;z-index:50;border-bottom:1px solid rgba(24,20,16,.08);background:rgba(248,244,237,.86);backdrop-filter:blur(16px) saturate(130%)}
.nav{min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;font-weight:900;letter-spacing:-.03em}
.mark{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(180deg,var(--brown),#4f2f1a);color:#fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.18)}
.navlinks{display:flex;gap:18px;color:var(--muted);font-size:13px}.navlinks a{text-decoration:none}.navlinks a:hover{color:var(--ink)}
.hero{padding:84px 0 46px}
.eyebrow{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:rgba(255,255,255,.45);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--brown)}
h1{margin:18px 0 16px;font:700 clamp(46px,8vw,88px)/.92 var(--serif);letter-spacing:-.065em;max-width:980px}
.lede{font-size:clamp(18px,2.1vw,24px);max-width:860px;color:#4e453d;margin:0}
.trilogy{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px}
.trilogy a,.trilogy span{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:999px;padding:8px 12px;font-size:11px;text-decoration:none;color:var(--muted);background:rgba(255,255,255,.42)}
.trilogy a:hover{color:var(--ink);border-color:var(--line-strong)}
.trilogy .active{background:var(--ink);color:#fff;border-color:var(--ink)}
.hero-grid{display:grid;grid-template-columns:1.4fr .95fr;gap:18px;margin-top:34px}
.surface{background:rgba(252,250,246,.86);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;padding:22px}
.kpi{padding:14px;border-radius:16px;background:rgba(255,255,255,.52);border:1px solid rgba(24,20,16,.05)}
.kpi strong{display:block;font:700 32px/1 var(--serif);letter-spacing:-.04em}
.kpi span{display:block;margin-top:8px;font-size:11px;line-height:1.3;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}
.note{padding:24px;background:linear-gradient(180deg,#271c16 0%, #1c1410 100%);color:#fff;position:relative;overflow:hidden}
.note::after{content:"";position:absolute;inset:auto -32px -46px auto;width:170px;height:170px;border-radius:40px;background:radial-gradient(circle at center,rgba(180,138,69,.2),transparent 65%)}
.note small{display:block;opacity:.74;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.note strong{display:block;font:700 28px/1.04 var(--serif);letter-spacing:-.035em;margin:14px 0 10px;max-width:380px}
.note p{margin:0;color:#d7cec3;font-size:13px;max-width:410px}
.cite{font-family:var(--mono);font-size:.62em;vertical-align:super;text-decoration:none;color:var(--olive);font-weight:700}
.note .cite{color:#e3c582}
section{padding:42px 0}
.section-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:18px}
.section-head h2{margin:6px 0 0;font:700 clamp(34px,4.5vw,52px)/.96 var(--serif);letter-spacing:-.05em}
.section-head p{margin:0;max-width:650px;color:var(--muted);font-size:14px}
.tabs{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 18px}
.tab{border:1px solid var(--line);background:rgba(255,255,255,.58);color:var(--muted);padding:10px 14px;border-radius:999px;cursor:pointer;font-size:12px;font-weight:700;letter-spacing:.02em}
.tab[aria-pressed="true"]{background:var(--ink);border-color:var(--ink);color:#fff}
.tab:focus-visible, button:focus-visible, a:focus-visible{outline:3px solid rgba(180,138,69,.3);outline-offset:3px}
.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}
.summary-card{padding:18px 18px 16px}
.summary-card small{display:block;font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);font-weight:800}
.summary-card strong{display:block;font:700 30px/1 var(--serif);letter-spacing:-.04em;margin-top:8px}
.summary-card span{display:block;margin-top:7px;font-size:12px;color:var(--muted)}
.dashboard{display:grid;grid-template-columns:1fr;gap:18px}
.stack{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.chart-card{padding:18px 18px 16px}
.chart-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:12px}
.chart-head h3{margin:0;font:700 28px/1.02 var(--serif);letter-spacing:-.03em}
.chart-head p{margin:6px 0 0;color:var(--muted);font-size:13px;max-width:470px}
.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}
.legend span{display:inline-flex;align-items:center;gap:7px}
.legend i{width:10px;height:10px;border-radius:999px;display:inline-block}
.legend .almond{background:var(--brown-2)}
.legend .pistachio{background:var(--olive)}
svg{display:block;width:100%;height:auto}
.corridor-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.corridor-panel{min-width:0;border:1px solid rgba(24,20,16,.06);border-radius:18px;background:linear-gradient(180deg,#fffdfa 0%,#f5eee3 100%);padding:14px 14px 10px;overflow:hidden}
.corridor-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:2px 4px 12px;border-bottom:1px solid rgba(24,20,16,.06)}
.corridor-panel-head div{display:flex;align-items:center;gap:8px}
.corridor-panel-head strong{font-size:14px}
.corridor-panel-head>span{font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.nut-key{width:10px;height:10px;border-radius:999px;display:inline-block}
.almond-key{background:var(--brown-2)}
.pistachio-key{background:var(--olive)}
.flow-ribbon{opacity:.78;transition:opacity .14s}
.flow-ribbon:hover{opacity:1}
.flow-source{fill:#201813}
.flow-source-label{font:800 12px/1 var(--sans);fill:#fff}
.flow-source-sub{font:600 10px/1 var(--sans);fill:#d8cfc7}
.flow-target{fill:#fff;stroke:#d8cdbf;stroke-width:1.2}
.flow-target-dot.almond{fill:var(--brown-2)}
.flow-target-dot.pistachio{fill:var(--olive)}
.flow-country{font:800 14px/1 var(--sans);fill:#24201c}
.flow-meta{font:600 11px/1 var(--sans);fill:#74695f}
.flow-rank{font:800 10px/1 var(--mono);fill:#9b8e81}
.flow-guide{stroke:#e2d8cb;stroke-width:1;stroke-dasharray:2 5}
text.axis,.scatter-label,.bubble-text{font:600 11px/1 var(--sans);fill:#6f655c}
line.axis,path.axis,line.grid{stroke:#ddd3c6;stroke-width:1}
.bar-track{fill:#ece3d6}
.bar-fill.almond{fill:var(--brown-2)}
.bar-fill.pistachio{fill:var(--olive)}
.bar-title{font:700 12px/1 var(--sans);fill:#28231f}
.bar-meta{font:600 11px/1 var(--sans);fill:#70665d}
.point.almond{fill:var(--brown-2)}
.point.pistachio{fill:var(--olive)}
.point-label{font:700 11px/1 var(--sans);fill:#2d2723}
.export-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.rank-card{padding:20px}
.rank-card h3{margin:0 0 14px;font:700 28px/1.02 var(--serif);letter-spacing:-.03em}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.card{padding:18px}
.card .number{font:700 34px/1 var(--serif);letter-spacing:-.04em}
.card h3{font:700 24px/1.05 var(--serif);margin:10px 0 6px}
.card p{margin:0;color:var(--muted);font-size:12px}
.card .meta{margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:18px;background:var(--paper);scrollbar-gutter:stable}
table{width:100%;border-collapse:collapse;table-layout:auto}
th,td{text-align:left;padding:14px 16px;border-bottom:1px solid var(--line);vertical-align:middle;white-space:nowrap}
th{position:sticky;top:65px;z-index:5;background:#efe6d8;font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
td{font-size:13px}
td.subtle{white-space:normal;min-width:160px}
tr:last-child td{border-bottom:0}
.mono{font-family:var(--mono)}
.rank{font:700 18px/1 var(--serif)}
.pill{display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;background:#eee2d3;color:#6f4428;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}
.pill.olive{background:#e4eadb;color:#4f6040}
.subtle{color:var(--muted)}
.footnote{margin-top:12px;font-size:12px;color:var(--muted)}
.split-dark{display:grid;grid-template-columns:1.25fr .95fr;gap:18px}
.dark{padding:24px;border-radius:var(--radius);background:linear-gradient(180deg,#1f1813 0%, #17110e 100%);color:#fff;box-shadow:var(--shadow)}
.dark h3{margin:12px 0 12px;font:700 34px/1 var(--serif);letter-spacing:-.04em;max-width:540px}
.dark p{margin:0;color:#d6cbbf;font-size:14px;max-width:720px}
.dark-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:20px}.dark-item{padding:14px 15px;border:1px solid rgba(255,255,255,.08);border-radius:16px;background:rgba(255,255,255,.03)}.dark-item b{display:block;font-size:13px}.dark-item span{display:block;margin-top:6px;font-size:12px;color:#ccbfae}
.method{padding:24px}
.method h3{margin:0 0 14px;font:700 30px/1.02 var(--serif);letter-spacing:-.03em}.method-row{padding:13px 0;border-top:1px solid var(--line)}.method-row:first-child{border-top:0}.method-row b{display:block;font-size:12px;letter-spacing:.08em;text-transform:uppercase}.method-row span{display:block;margin-top:6px;color:var(--muted);font-size:13px}
.sources{display:grid;grid-template-columns:1fr 1fr;gap:10px}.source-row{display:flex;justify-content:space-between;gap:16px;padding:14px 0;border-top:1px solid var(--line);font-size:13px}.source-row:first-child{border-top:0}.source-row span{display:block;color:var(--muted);max-width:48%;text-align:right}
.footer{padding:44px 0 72px;border-top:1px solid rgba(24,20,16,.08);color:var(--muted);font-size:12px}
.tooltip{position:fixed;z-index:60;pointer-events:none;opacity:0;transform:translate(-50%,-118%);background:#17120e;color:#fff;padding:10px 12px;border-radius:12px;box-shadow:0 14px 36px rgba(0,0,0,.22);font-size:12px;max-width:290px;transition:opacity .12s}.tooltip b{display:block;margin-bottom:4px}.tooltip span{color:#d9cec2}
[data-hidden="true"]{display:none!important}
@media (max-width:1100px){
  .hero-grid,.dashboard,.export-grid,.cards,.split-dark,.summary-grid{grid-template-columns:1fr 1fr}
  .kpis{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:860px){
  .navlinks{display:none}
  .hero,.section-head{display:block}
  .hero-grid,.dashboard,.export-grid,.cards,.split-dark,.summary-grid,.corridor-grid,.stack{grid-template-columns:1fr}
  .kpis{grid-template-columns:1fr 1fr}
  .sources{grid-template-columns:1fr}
  .source-row{display:block}.source-row span{max-width:none;text-align:left;margin-top:6px}

  /* Tables become structured data cards instead of horizontal-scroll spreadsheets. */
  .table-wrap{overflow:visible;border:0;border-radius:0;background:transparent}
  .table-wrap table{display:block;width:100%;min-width:0}
  .table-wrap thead{display:none}
  .table-wrap tbody{display:grid;gap:12px}
  .table-wrap tr{
    display:grid;
    grid-template-columns:repeat(4,minmax(0,1fr));
    border:1px solid var(--line);
    border-radius:16px;
    background:var(--paper);
    box-shadow:0 8px 24px rgba(48,32,20,.045);
    overflow:hidden;
  }
  .table-wrap td{
    display:block;
    min-width:0;
    padding:12px 13px;
    border:0;
    border-right:1px solid var(--line);
    border-bottom:1px solid var(--line);
    white-space:normal;
    overflow-wrap:anywhere;
    font-size:12px;
  }
  .table-wrap td::before{
    content:attr(data-label);
    display:block;
    margin-bottom:5px;
    font:800 9px/1.15 var(--mono);
    letter-spacing:.08em;
    text-transform:uppercase;
    color:var(--muted);
  }
  .table-wrap td:nth-child(4n){border-right:0}
  .table-wrap td:nth-last-child(-n+4){border-bottom:0}
  .table-wrap td.subtle{min-width:0}
  .table-wrap .rank{font-size:20px}
}
@media (max-width:560px){
  .wrap{width:min(100% - 24px,1240px)}
  .hero{padding-top:72px}
  h1{font-size:42px}
  .kpis{grid-template-columns:1fr}
  .summary-card strong,.card .number{font-size:28px}
  th{top:0}
  .table-wrap tr{grid-template-columns:repeat(2,minmax(0,1fr))}
  .table-wrap td:nth-child(4n){border-right:1px solid var(--line)}
  .table-wrap td:nth-child(2n){border-right:0}
  .table-wrap td:nth-last-child(-n+4){border-bottom:1px solid var(--line)}
  .table-wrap td:nth-last-child(-n+2){border-bottom:0}
}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}.tooltip{transition:none}}
@media print{.topbar,.tabs,.tooltip{display:none!important}body{background:#fff}.surface,.dark{box-shadow:none}}

script:
(() => {
  'use strict';
  const SOURCES={almond24:'#s-almond-us24',pist24:'#s-pist-us24',almondWorld:'#s-almond-world24',pistWorld:'#s-pist-world24'};
  const ROUTES=Object.freeze([
    {nut:'almond',origin:'United States',destination:'Spain',region:'Europe',tonnes:82638.5,valueM:360.03244,totalTonnes:716378,source:SOURCES.almond24},
    {nut:'almond',origin:'United States',destination:'United Arab Emirates',region:'Gulf',tonnes:68421.6,valueM:351.80433,totalTonnes:716378,source:SOURCES.almond24},
    {nut:'almond',origin:'United States',destination:'Netherlands',region:'Europe',tonnes:59044.8,valueM:278.02208,totalTonnes:716378,source:SOURCES.almond24},
    {nut:'almond',origin:'United States',destination:'Türkiye',region:'East Med',tonnes:54498.1,valueM:268.03660,totalTonnes:716378,source:SOURCES.almond24},
    {nut:'almond',origin:'United States',destination:'Japan',region:'East Asia',tonnes:40925.8,valueM:210.30679,totalTonnes:716378,source:SOURCES.almond24},
    {nut:'pistachio',origin:'United States',destination:'China',region:'East Asia',tonnes:93933.2,valueM:633.55541,totalTonnes:348310,source:SOURCES.pist24},
    {nut:'pistachio',origin:'United States',destination:'Germany',region:'Europe',tonnes:40099.9,valueM:294.95380,totalTonnes:348310,source:SOURCES.pist24},
    {nut:'pistachio',origin:'United States',destination:'Vietnam',region:'East Asia',tonnes:32374.7,valueM:237.61071,totalTonnes:348310,source:SOURCES.pist24},
    {nut:'pistachio',origin:'United States',destination:'Türkiye',region:'East Med',tonnes:22133.0,valueM:140.04523,totalTonnes:348310,source:SOURCES.pist24},
    {nut:'pistachio',origin:'United States',destination:'India',region:'South Asia',tonnes:15312.5,valueM:116.37454,totalTonnes:348310,source:SOURCES.pist24}
  ].map(r=>({...r,unitValue:r.valueM*1e6/(r.tonnes*1000),share:100*r.tonnes/r.totalTonnes})));

  const EXPORTERS=Object.freeze([
    {nut:'Almond',rank:1,country:'United States',valueM:3522.09627,tonnes:716378,role:'Producer/exporter',pill:'almond',source:SOURCES.almondWorld},
    {nut:'Almond',rank:2,country:'Spain',valueM:650.83379,tonnes:121888,role:'Producer + EU processor',pill:'almond',source:SOURCES.almondWorld},
    {nut:'Almond',rank:3,country:'Australia',valueM:430.30956,tonnes:89106.5,role:'Producer/exporter',pill:'almond',source:SOURCES.almondWorld},
    {nut:'Almond',rank:4,country:'Türkiye',valueM:167.36319,tonnes:32087.9,role:'Producer/trader',pill:'almond',source:SOURCES.almondWorld},
    {nut:'Pistachio',rank:1,country:'United States',valueM:2508.88627,tonnes:348310,role:'Producer/exporter',pill:'pistachio',source:SOURCES.pistWorld},
    {nut:'Pistachio',rank:2,country:'Türkiye',valueM:444.68071,tonnes:41156.5,role:'Producer/exporter',pill:'pistachio',source:SOURCES.pistWorld},
    {nut:'Pistachio',rank:3,country:'Germany',valueM:195.60753,tonnes:17290.7,role:'Processor/re-export hub',pill:'pistachio',source:SOURCES.pistWorld},
    {nut:'Pistachio',rank:4,country:'Netherlands',valueM:66.69328,tonnes:6667.15,role:'Trade/re-export hub',pill:'pistachio',source:SOURCES.pistWorld},
    {nut:'Pistachio',rank:5,country:'Spain',valueM:51.85102,tonnes:4790.48,role:'Producer/processor',pill:'pistachio',source:SOURCES.pistWorld}
  ].map(r=>({...r,unitValue:r.valueM*1e6/(r.tonnes*1000)})));

  const fmtTon=v=>`${v.toLocaleString('en-US',{maximumFractionDigits:1})} t`;
  const fmtMoney=v=>v>=1000?`$${(v/1000).toFixed(2)}B`:`$${v.toFixed(1)}M`;
  const fmtUnit=v=>`$${v.toFixed(2)}/kg`;
  const fmtShare=v=>`${v.toFixed(1)}%`;
  const nutLabel=n=>n==='almond'?'Almond':'Pistachio';
  const nutColor=n=>n==='almond'?'var(--brown-2)':'var(--olive)';
  const tip=document.getElementById('tooltip');
  const q=(sel)=>document.querySelector(sel);
  const text=(tag,val,cls)=>{const n=document.createElement(tag);if(cls)n.className=cls;n.textContent=val;return n};
  let filter='all';

  function getData(){
    if(filter==='all') return [...ROUTES].sort((a,b)=>b.tonnes-a.tonnes);
    return ROUTES.filter(r=>r.nut===filter).sort((a,b)=>b.tonnes-a.tonnes);
  }

  function showTip(evt, html){
    tip.innerHTML=html;
    tip.style.left=`${evt.clientX}px`;
    tip.style.top=`${evt.clientY}px`;
    tip.style.opacity='1';
  }
  function hideTip(){ tip.style.opacity='0'; }

  function renderSummary(){
    const box=q('#summaryCards'); box.innerHTML='';
    const data=getData();
    const totalTonnes=filter==='all' ? data.reduce((s,r)=>s+r.tonnes,0) : data[0]?.totalTonnes || 0;
    const totalValue=data.reduce((s,r)=>s+r.valueM,0);
    const top=data[0];
    const almondShown=ROUTES.filter(r=>r.nut==='almond').reduce((s,r)=>s+r.share,0);
    const pistShown=ROUTES.filter(r=>r.nut==='pistachio').reduce((s,r)=>s+r.share,0);
    const shownShare=filter==='all' ? null : data.reduce((s,r)=>s+r.share,0);
    const weightedUnit=totalTonnes ? totalValue*1e6/(totalTonnes*1000) : 0;
    const items=[
      {label:filter==='all'?'Volume shown':'Mapped volume',value:fmtTon(totalTonnes),meta:filter==='all'?'Top five destinations for each nut':'Selected corridor set'},
      {label:'Mapped value',value:fmtMoney(totalValue),meta:'Customs value across selected routes'},
      {label:'Largest route',value: top ? `${top.destination}` : '—',meta: top ? `${fmtTon(top.tonnes)} · ${fmtShare(top.share)} of U.S. ${top.nut}` : '—'},
      {label:filter==='all'?'Displayed coverage':'Weighted unit value',value:filter==='all'?'10 routes':fmtUnit(weightedUnit),meta:filter==='all'?`${fmtShare(almondShown)} of almonds shown · ${fmtShare(pistShown)} of pistachios shown`:'Selected-route weighted customs value'}
    ];
    items.forEach(it=>{
      const card=document.createElement('article'); card.className='surface summary-card';
      card.append(text('small',it.label)); card.append(text('strong',it.value)); card.append(text('span',it.meta)); box.append(card);
    });
  }

  function renderSingleFlow(nut, svgSelector){
    const svg=q(svgSelector);
    const data=ROUTES.filter(r=>r.nut===nut).sort((a,b)=>b.tonnes-a.tonnes);
    const W=540,H=420;
    const sourceX=58, sourceW=26, targetX=300, targetW=12;
    const top=82, bottom=366, gap=14;
    const shownTotal=data.reduce((s,r)=>s+r.tonnes,0);
    const usableH=(bottom-top)-gap*(data.length-1);
    const heights=data.map(r=>Math.max(18, usableH*(r.tonnes/shownTotal)));
    const scaleFix=usableH/heights.reduce((s,h)=>s+h,0);
    const scaled=heights.map(h=>h*scaleFix);
    const sourceTop=top;
    const sourceHeight=scaled.reduce((s,h)=>s+h,0);
    let sourceCursor=sourceTop;
    let targetCursor=top;
    const fill=nut==='almond' ? '#a86b3b' : '#5d6f4c';
    const fillSoft=nut==='almond' ? '#d7b493' : '#b7c3a0';

    let html='';
    html += `<text x="${sourceX-4}" y="38" class="flow-rank">ORIGIN</text>`;
    html += `<text x="${targetX}" y="38" class="flow-rank">DESTINATIONS</text>`;
    html += `<line x1="${targetX}" x2="${W-18}" y1="50" y2="50" class="flow-guide"></line>`;

    html += `<rect x="${sourceX}" y="${sourceTop}" width="${sourceW}" height="${sourceHeight}" rx="13" class="flow-source"></rect>`;
    html += `<text x="${sourceX+sourceW/2}" y="${sourceTop-20}" text-anchor="middle" class="flow-country">U.S.</text>`;
    html += `<text x="${sourceX+sourceW/2}" y="${sourceTop-6}" text-anchor="middle" class="flow-meta">top 5 shown</text>`;

    data.forEach((r,i)=>{
      const h=scaled[i];
      const sy0=sourceCursor, sy1=sourceCursor+h;
      const ty0=targetCursor, ty1=targetCursor+h;
      const c1=155, c2=235;
      const d=`M ${sourceX+sourceW} ${sy0}
               C ${c1} ${sy0}, ${c2} ${ty0}, ${targetX} ${ty0}
               L ${targetX} ${ty1}
               C ${c2} ${ty1}, ${c1} ${sy1}, ${sourceX+sourceW} ${sy1} Z`;
      html += `<path d="${d}" fill="${fill}" class="flow-ribbon" data-tip="${r.origin} → ${r.destination}|${nutLabel(r.nut)} · ${fmtTon(r.tonnes)} · ${fmtMoney(r.valueM)} · ${fmtShare(r.share)} of total U.S. ${r.nut} exports"></path>`;
      html += `<rect x="${targetX}" y="${ty0}" width="${targetW}" height="${h}" rx="${Math.min(6,h/2)}" class="flow-target"></rect>`;
      html += `<rect x="${targetX+2}" y="${ty0+2}" width="${targetW-4}" height="${Math.max(4,h-4)}" rx="${Math.min(4,Math.max(2,(h-4)/2))}" fill="${fillSoft}"></rect>`;
      html += `<circle cx="${targetX+targetW/2}" cy="${ty0+h/2}" r="3.5" class="flow-target-dot ${nut}"></circle>`;
      const labelY=ty0+h/2;
      html += `<text x="${targetX+28}" y="${labelY-5}" class="flow-country">${i+1}. ${r.destination}</text>`;
      html += `<text x="${targetX+28}" y="${labelY+11}" class="flow-meta">${fmtTon(r.tonnes)} · ${fmtShare(r.share)} · ${fmtUnit(r.unitValue)}</text>`;
      if(i<data.length-1) html += `<line x1="${targetX+28}" x2="${W-18}" y1="${ty1+gap/2}" y2="${ty1+gap/2}" class="flow-guide"></line>`;
      sourceCursor += h;
      targetCursor += h+gap;
    });

    const shownShare=data.reduce((s,r)=>s+r.share,0);
    html += `<text x="${sourceX}" y="${H-16}" class="flow-meta">${fmtTon(shownTotal)} shown · ${fmtShare(shownShare)} of total U.S. ${nut} volume</text>`;
    svg.innerHTML=html;

    svg.querySelectorAll('.flow-ribbon').forEach(path=>{
      path.addEventListener('mousemove',e=>{const [title,body]=path.dataset.tip.split('|');showTip(e,`<b>${title}</b><span>${body}</span>`)});
      path.addEventListener('mouseleave',hideTip);
    });
  }

  function renderFlow(){
    const selected = filter==='all' ? ['almond','pistachio'] : [filter];
    const almondPanel=q('.almond-panel');
    const pistPanel=q('.pistachio-panel');
    almondPanel.hidden=!selected.includes('almond');
    pistPanel.hidden=!selected.includes('pistachio');
    renderSingleFlow('almond','#almondFlowChart');
    renderSingleFlow('pistachio','#pistachioFlowChart');
  }

  function renderBarChart(){
    const svg=q('#barChart');
    const data=getData();
    const W=620, rowH=48, chartTop=24, bottom=38;
    const H=chartTop + data.length*rowH + bottom;
    svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
    const chartX=176, chartW=W-chartX-36, max=Math.max(...data.map(r=>r.tonnes));
    let html='';
    [0,.25,.5,.75,1].forEach(fr=>{
      const x=chartX+chartW*fr;
      html += `<line x1="${x}" y1="${chartTop}" x2="${x}" y2="${H-bottom}" class="grid"></line>`;
      html += `<text x="${x}" y="${H-12}" text-anchor="middle" class="axis">${Math.round(max*fr/1000)}k</text>`;
    });
    data.forEach((r,i)=>{
      const y=chartTop+i*rowH;
      const w=chartW*(r.tonnes/max);
      const color=r.nut==='almond'?'almond':'pistachio';
      html += `<text x="18" y="${y+16}" class="bar-title">${r.destination}</text>`;
      html += `<text x="18" y="${y+31}" class="bar-meta">${nutLabel(r.nut)} · ${r.region}</text>`;
      html += `<rect x="${chartX}" y="${y+3}" width="${chartW}" height="16" rx="8" class="bar-track"></rect>`;
      html += `<rect x="${chartX}" y="${y+3}" width="${w}" height="16" rx="8" class="bar-fill ${color}"></rect>`;
      html += `<text x="${Math.min(chartX+w+8,W-118)}" y="${y+16}" class="bar-meta">${fmtTon(r.tonnes)} · ${fmtShare(r.share)}</text>`;
    });
    svg.innerHTML=html;
  }

  function renderScatter(){
    const svg=q('#scatterChart');
    const data=getData();
    const W=620,H=440,m={t:28,r:28,b:48,l:58};
    svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
    const maxX=Math.max(...data.map(r=>r.tonnes))*1.10;
    const maxY=Math.max(...data.map(r=>r.unitValue))*1.13;
    const x=v=>m.l+(v/maxX)*(W-m.l-m.r);
    const y=v=>H-m.b-(v/maxY)*(H-m.t-m.b);
    let html='';

    [0,.25,.5,.75,1].forEach(fr=>{
      const xv=maxX*fr, px=x(xv);
      html += `<line x1="${px}" y1="${m.t}" x2="${px}" y2="${H-m.b}" class="grid"></line>`;
      html += `<text x="${px}" y="${H-16}" text-anchor="middle" class="axis">${Math.round(xv/1000)}k</text>`;
    });
    [0,.25,.5,.75,1].forEach(fr=>{
      const yv=maxY*fr, py=y(yv);
      html += `<line x1="${m.l}" y1="${py}" x2="${W-m.r}" y2="${py}" class="grid"></line>`;
      html += `<text x="${m.l-10}" y="${py+4}" text-anchor="end" class="axis">$${yv.toFixed(1)}</text>`;
    });
    html += `<text x="${(W+m.l-m.r)/2}" y="${H-2}" text-anchor="middle" class="axis">Volume (tonnes)</text>`;
    html += `<text x="16" y="${(H+m.t-m.b)/2}" text-anchor="middle" class="axis" transform="rotate(-90 16 ${(H+m.t-m.b)/2})">Customs unit value ($/kg)</text>`;

    const offsets={
      'pistachio:China':[-62,-18],
      'almond:Spain':[12,24],
      'almond:United Arab Emirates':[12,-12],
      'almond:Netherlands':[12,24],
      'almond:Türkiye':[12,-18],
      'almond:Japan':[12,-14],
      'pistachio:Germany':[12,-18],
      'pistachio:Vietnam':[12,22],
      'pistachio:Türkiye':[-60,20],
      'pistachio:India':[12,-16]
    };

    data.forEach(r=>{
      const px=x(r.tonnes), py=y(r.unitValue), rad=5+Math.min(8,r.share/3);
      const key=`${r.nut}:${r.destination}`;
      const [dx,dy]=offsets[key] || [12,-10];
      const lx=px+dx, ly=py+dy;
      html += `<circle cx="${px}" cy="${py}" r="${rad}" class="point ${r.nut}" fill-opacity=".9"></circle>`;
      html += `<line x1="${px}" y1="${py}" x2="${lx+(dx<0?48:-4)}" y2="${ly-3}" class="flow-guide"></line>`;
      html += `<text x="${lx}" y="${ly}" class="point-label">${r.destination}</text>`;
      html += `<circle cx="${px}" cy="${py}" r="${rad+10}" fill="transparent" data-tip="${r.destination}|${nutLabel(r.nut)} · ${fmtTon(r.tonnes)} · ${fmtMoney(r.valueM)} · ${fmtUnit(r.unitValue)}" class="scatter-hit"></circle>`;
    });

    svg.innerHTML=html;
    svg.querySelectorAll('.scatter-hit').forEach(hit=>{
      hit.addEventListener('mousemove',e=>{const [title,body]=hit.dataset.tip.split('|');showTip(e,`<b>${title}</b><span>${body}</span>`)});
      hit.addEventListener('mouseleave',hideTip);
    });
  }

  function renderExportersChart(nut, svgId){
    const svg=q(svgId); const data=EXPORTERS.filter(r=>r.nut.toLowerCase()===nut).sort((a,b)=>b.valueM-a.valueM);
    const W=520,H=nut==='almond'?320:360, chartX=140, chartW=330, rowH=54, top=18, max=Math.max(...data.map(r=>r.valueM));
    let html='';
    [0,.25,.5,.75,1].forEach(fr=>{ const x=chartX+chartW*fr; html += `<line x1="${x}" y1="${top}" x2="${x}" y2="${H-34}" class="grid"></line>`; html += `<text x="${x}" y="${H-10}" text-anchor="middle" class="axis">${fr===1?fmtMoney(max):fr===0?'0':fmtMoney(max*fr)}</text>`;});
    data.forEach((r,i)=>{
      const y=top+i*rowH; const w=(r.valueM/max)*chartW; const color=nut==='almond'?'almond':'pistachio';
      html += `<text x="18" y="${y+18}" class="bar-title">${r.country}</text>`;
      html += `<text x="18" y="${y+34}" class="bar-meta">#${r.rank} · ${r.role}</text>`;
      html += `<rect x="${chartX}" y="${y+2}" width="${chartW}" height="18" rx="9" class="bar-track"></rect>`;
      html += `<rect x="${chartX}" y="${y+2}" width="${w}" height="18" rx="9" class="bar-fill ${color}"></rect>`;
      html += `<text x="${chartX+w+8}" y="${y+16}" class="bar-meta">${fmtMoney(r.valueM)}</text>`;
    });
    svg.innerHTML=html;
  }

  function renderTables(){
    const makeCell=(value,label,cls='')=>{
      const td=text('td',value,cls);
      td.dataset.label=label;
      return td;
    };
    const makeLinkCell=(label,linkText,href,newTab=false)=>{
      const td=document.createElement('td');
      td.dataset.label=label;
      const a=text('a',linkText);
      a.href=href;
      if(newTab){a.target='_blank';a.rel='noopener';}
      td.append(a);
      return td;
    };

    const exp=q('#exporterRows');
    exp.innerHTML='';
    EXPORTERS.forEach(x=>{
      const tr=document.createElement('tr');

      const nut=document.createElement('td');
      nut.dataset.label='Nut';
      const pill=text('span',x.nut,'pill ' + (x.pill==='pistachio'?'olive':''));
      nut.append(pill);
      tr.append(nut);

      tr.append(makeCell(String(x.rank),'Rank','rank'));
      tr.append(makeCell(x.country,'Exporter'));
      tr.append(makeCell(fmtMoney(x.valueM),'Value','mono'));
      tr.append(makeCell(fmtTon(x.tonnes),'Volume','mono'));
      tr.append(makeCell(fmtUnit(x.unitValue),'Unit value','mono'));
      tr.append(makeCell(x.role,'Role','subtle'));
      tr.append(makeLinkCell('Source','Open ↗',x.source,true));
      exp.append(tr);
    });

    const ledger=q('#routeRows');
    ledger.innerHTML='';
    ROUTES.forEach(r=>{
      const tr=document.createElement('tr');

      const nut=document.createElement('td');
      nut.dataset.label='Nut';
      const pill=text('span',nutLabel(r.nut),'pill ' + (r.nut==='pistachio'?'olive':''));
      nut.append(pill);
      tr.append(nut);

      tr.append(makeCell(r.origin,'Origin'));
      tr.append(makeCell(r.destination,'Destination'));
      tr.append(makeCell(r.region,'Region','subtle'));
      tr.append(makeCell(fmtTon(r.tonnes),'Volume','mono'));
      tr.append(makeCell(fmtMoney(r.valueM),'Value','mono'));
      tr.append(makeCell(fmtUnit(r.unitValue),'Unit value','mono'));
      tr.append(makeCell(fmtShare(r.share),'U.S. share','mono'));
      tr.append(makeLinkCell('Source','Source ↗',r.source,false));
      ledger.append(tr);
    });
  }

  function update(){
    renderSummary(); renderFlow(); renderBarChart(); renderScatter();
  }

  q('.tabs').addEventListener('click',e=>{
    const btn=e.target.closest('[data-filter]'); if(!btn) return;
    filter=btn.dataset.filter;
    document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed', String(b===btn)));
    update();
  });

  renderExportersChart('almond','#almondExportersChart');
  renderExportersChart('pistachio','#pistachioExportersChart');
  renderTables();
  update();
})();
